"💡 Верно. Вальс считают раз-два-три": "💡 Дуруст. Вальсро якум-дуюм-сеюм мешуморанд",
"💡 Верно. Две восьмые — это один счёт": "💡 Дуруст. Ду ҳаштӣ — ин як ҳисоб аст",
