"В семейном архиве хранят старые фотографии, письма и документы. По ним можно узнать историю семьи.": "Дар бойгонии оилавӣ суратҳои кӯҳна, номаҳо ва ҳуҷҷатҳоро нигоҳ медоранд. Аз рӯи онҳо таърихи оиларо фаҳмидан мумкин аст.",
