"Газировку можно пить вместо воды каждый день": "Нӯшобаи газдорро ҳар рӯз ба ҷои об нӯшидан мумкин аст",
"Где Солнце садится?": "Офтоб дар куҷо ғуруб мекунад?",
"Где безопаснее всего во время грозы?": "Ҳангоми раъду барқ дар куҷо аз ҳама бехатар аст?",
"Где в Казахстане находится курорт Бурабай?": "Истироҳатгоҳи Бурабай дар Қазоқистон дар куҷост?",
"Где идёт дождь": "Он ҷое, ки борон меборад",
"Где лучше выращивать пшеницу?": "Гандумро дар куҷо беҳтар парвариш кардан мумкин аст?",
"Где находилось поселение Ботай?": "Ҷойгоҳи Ботай дар куҷо буд?",
"Где находится дом": "Он ҷое, ки хона аст",
"Где нужно ждать автобус?": "Автобусро дар куҷо интизор шудан лозим аст?",
"Где он купил одежду": "Дар куҷо ӯ либос харид",
"Где утром встаёт Солнце?": "Офтоб субҳ дар куҷо тулӯъ мекунад?",
"Где-то жить удобно: тёплое лето, чистая река, плодородная земля. А где-то трудно: сильные ветры или мало воды.": "Дар ягон ҷо зиндагӣ кардан қулай аст: тобистони гарм, дарёи тоза, замини ҳосилхез. Дар ягон ҷои дигар душвор аст: бодҳои сахт ё обаш кам.",
"Герб Казахстана — это изображение шанырака, тулпаров и звезды": "Нишони давлатии Қазоқистон — тасвири шанирақ, тулпорҳо ва ситора аст",
"Герб изображён на государственных документах, например на паспорте": "Нишони давлатӣ дар ҳуҷҷатҳои давлатӣ тасвир шудааст, масалан дар шиноснома",
"Гимн Казахстана можно петь неуважительно": "Суруди миллии Қазоқистонро бе эҳтиром хондан мумкин аст",
"Гимн исполняют на церемониях и соревнованиях": "Суруди миллиро дар маросимҳо ва мусобиқаҳо иҷро мекунанд",
"Гимн слушают стоя в знак уважения": "Суруди миллиро ба аломати эҳтиром ба по истода гӯш мекунанд",
"Гимн — торжественная песня страны. Его слушают стоя, так выражают уважение к стране.": "Суруди милли — суруди тантанавии кишвар аст. Онро ба по истода гӯш мекунанд, ин тавр эҳтиромро ба кишвар ифода мекунанд.",
"Говорить правду": "Рост гуфтан",
"Говорить правду родным — хорошее семейное правило": "Ба наздикон рост гуфтан — қоидаи хуби оилавӣ аст",
"Гололёд": "Яхбандии роҳ",
"Голубым цветом": "Бо ранги осмонӣ",
"Горнолыжный курорт Шымбулак находится рядом с Алматы": "Истироҳатгоҳи кӯҳии лижаронӣ Шимбулоқ дар наздикии Алмаато ҷойгир аст",
"Горнолыжный курорт недалеко от Алматы": "Истироҳатгоҳи кӯҳии лижаронӣ дар наздикии Алмаато",
"Горный поход к вершине": "Сафари кӯҳӣ ба қуллаи кӯҳ",
"Город Туркестан известен мавзолеем Ходжи Ахмеда Ясави": "Шаҳри Туркистон бо мақбараи Хоҷа Аҳмад Яссавӣ маъруф аст",
"Городище Отрар": "Шаҳристони Ӯтрор",
"Горы": "Кӯҳҳо",
"Горы дают много пшеницы": "Кӯҳҳо гандуми бисёр медиҳанд",
"Государственные символы Казахстана — флаг, герб и гимн.": "Рамзҳои давлатии Қазоқистон — парчам, нишон ва суруди миллӣ аст.",
"Государственный язык Казахстана — казахский": "Забони давлатии Қазоқистон — қазоқӣ аст",
"Готовит обед": "Хӯроки нисфирӯзӣ мепазад",
"Градом называют ледяные шарики, которые падают с неба": "Жола — ин тӯбчаҳои яхин аст, ки аз осмон меафтанд",
"Гроза с молнией": "Раъду барқ бо барқ",
"Гроза — безопасное время для купания в реке": "Раъду барқ — вақти бехатар барои оббозӣ дар дарё аст",
"Грубить старшим": "Ба калонсолон дурушт гуфтан",
"Грязный двор мешает всем": "Ҳавлии ифлос ба ҳама халал мерасонад",
"Гунны были кочевниками": "Ҳунҳо кӯчманчӣ буданд",
"Гунны были отличными всадниками": "Ҳунҳо аспсавороне буданд, ки аъло савор мешуданд",
"Густой туман": "Туманди ғафс",
"Дают воду, электричество и путь для судов": "Об, барқ ва роҳ барои киштиҳо медиҳанд",
"Дают нам шоколад": "Ба мо шоколад медиҳанд",
"Делать опыт на естествознании": "Дар дарси табиатшиносӣ таҷриба кардан",
"Делают погоду жаркой": "Обу ҳаворо гарм мекунанд",
"День Конституции": "Рӯзи Конститутсия",
"День Победы": "Рӯзи Ғалаба",
"День Победы отмечают 9 января": "Рӯзи Ғалабаро 9 январ ҷашн мегиранд",
"День единства народа Казахстана": "Рӯзи ваҳдати халқи Қазоқистон",
