"Деньги семьи — это зарплата взрослых за работу. Сначала их тратят на то, что нужно.": "Пули оила — ин музди меҳнати калонсолон барои кор аст. Аввал онро ба он чи лозим аст, сарф мекунанд.",
"Деньги семья получает, когда взрослые работают": "Оила пул мегирад, вақте ки калонсолон кор мекунанд",
"Деревья очищают воздух": "Дарахтон ҳаворо тоза мекунанд",
"Держаться за поручень": "Ба дастгир такя кардан",
"Дети имеют право на любовь и заботу": "Кӯдакон ба муҳаббат ва ғамхорӣ ҳуқуқ доранд",
"Директор": "Директор",
"Директор отвечает за всю школу": "Директор барои тамоми мактаб масъул аст",
"Дичь живёт в природе, человек её добывает": "Шикор дар табиат зиндагӣ мекунад, одам онро ба даст меорад",
"Для горного похода достаточно лёгких шлёпанцев": "Барои сафари кӯҳӣ шиппаки сабук кифоя аст",
"Для сильных и подготовленных туристов": "Барои сайёҳони пурзӯр ва омодашуда",
"Добывать руду и камень": "Маъдан ва санг истихроҷ кардан",
