"Долгая засуха": "Хушксолии дароз",
"Дом, где живут бабушки": "Хонае, ки бибиҳо дар он зиндагӣ мекунанд",
"Домашнее задание": "Вазифаи хонагӣ",
"Достопримечательность — интересное место, которым гордятся жители. О нём можно рассказать, нарисовать его или сделать макет.": "Ҷои дидание — ҷои шавқоварест, ки сокинон бо он фахр мекунанд. Дар бораи он нақл кардан, онро кашидан ё макети онро сохтан мумкин аст.",
"Драконы": "Аждаҳо",
"Древние люди сразу строили небоскрёбы": "Одамони қадим фавран осмонбӯсҳо месохтанд",
"Древние рисунки на скалах в Алматинской области": "Расмҳои қадимӣ дар сангҳо дар вилояти Алмаато",
"Дружба народов — сила нашей страны": "Дӯстии халқҳо — қуввати кишвари мост",
"Друзьям нужно быть вежливыми, не обзываться и просить прощения, если обидел.": "Дӯстон бояд хушмуомила бошанд, номҳои бад нагузоранд ва агар ранҷонанд, бубахшиш пурсанд.",
