"Еда, одежда и жильё": "Хӯрок, либос ва манзил",
"Едет по дороге": "Дар роҳ меравад",
"Едет по дорожке": "Дар пиёдараҳа меравад",
"Едет по рельсам": "Бар рельсҳо меравад",
"Единороги": "Яккашохҳо",
"Если обидел одноклассника, надо извиниться": "Агар ҳамсинфро ранҷонидӣ, бояд бубахшиш пурсӣ",
"Есть вода для людей и полей": "Об барои одамон ва киштзорҳо ҳаст",
