"Подарок от родителей": "Туҳфа аз падару модар",
"Подарок — один из способов получить вещь": "Туҳфа — яке аз роҳҳои ба даст овардани чиз аст",
"Поднимается в воздух": "Ба ҳаво баланд мешавад",
"Поезд": "Қатора",
"Поздравляю! Ты узнал про семью, школу, родной край, карту, город, права, погоду, путешествия, историю и символы Казахстана. Теперь закрепляй знания в играх.": "Табрик мекунам! Ту дар бораи оила, мактаб, Ватани хурд, харита, шаҳр, ҳуқуқҳо, обу ҳаво, сафарҳо, таърих ва рамзҳои Қазоқистон фаҳмидӣ. Акнун донишро дар бозиҳо мустаҳкам кун.",
"Познавательный": "Маърифатӣ",
"Познавательный туризм: едут узнавать новое. Например, в Туркестан к мавзолею Ходжи Ахмеда Ясави.": "Туризми маърифатӣ: барои омӯхтани чизи нав мераванд. Масалан, ба Туркистон ба мақбараи Хоҷа Аҳмад Яссавӣ.",
"Пойти с незнакомым человеком": "Бо шахси бегона рафтан",
