"Сель — опасное явление в горах: грязевой поток. Рядом с горными реками нужно быть осторожным.": "Сел — падидаи хатарнок дар кӯҳҳо аст: ҷараёни лой. Дар назди дарёҳои кӯҳӣ бояд эҳтиёт буд.",
"Сель — это опасное явление природы": "Сел — падидаи хатарноки табиӣ аст",
"Семейные правила помогают всем жить дружно": "Қоидаҳои оилавӣ ба ҳама кумак мекунанд, ки дӯстона зиндагӣ кунанд",
