"Снег укрывает землю и весной даёт воду полям": "Барф заминро мепӯшонад ва баҳор ба киштзорҳо об медиҳад",
"Собирать портфель": "Ҷузвдонро ҷамъ кардан",
"Соблюдать школьные правила": "Қоидаҳои мактабро риоя кардан",
"Солнце встаёт на востоке, а садится на западе. В полдень Солнце у нас стоит на юге.": "Офтоб дар шарқ тулӯъ мекунад ва дар ғарб ғуруб мекунад. Дар нисфирӯзӣ Офтоб дар назди мо дар ҷануб меистад.",
"Солнце встаёт на западе": "Офтоб дар ғарб тулӯъ мекунад",
"Солнце — символ жизни и тепла": "Офтоб — рамзи ҳаёт ва гармӣ аст",
"Сосчитать, сколько на снимке окон": "Шумурдан, ки дар акс чанд тиреза ҳаст",
"Список покупок": "Рӯйхати харид",
"Сплав по горной реке": "Рафтинг дар дарёи кӯҳӣ",
"Спортивный": "Варзишӣ",
"Спортивный туризм: катаются на лыжах, ходят в горные походы, сплавляются по рекам.": "Туризми варзишӣ: лижаронӣ мекунанд, ба сафарҳои кӯҳӣ мераванд, дар дарёҳо рафтинг мекунанд.",
"Спросить у прохожего": "Аз роҳгузар пурсидан",
"Спрятать рисунок": "Расмро пинҳон кардан",
"Старшим надо отвечать вежливо": "Ба калонсолон бояд хушмуомилагӣ ҷавоб дод",
"Старших в семье можно не слушать": "Калонсолони оиларо гӯш накардан мумкин аст",
"Старые фотографии и бумаги семьи, которые хранят": "Суратҳо ва ҳуҷҷатҳои кӯҳнаи оила, ки нигоҳ дошта мешаванд",
"Стены принадлежат всем жителям": "Деворҳо ба ҳамаи сокинон тааллуқ доранд",
"Стороны горизонта помогают не потеряться, а знания о погоде — вести себя безопасно. Нажимай на карточки.": "Тарафҳои уфуқ ба гум нашудан кумак мекунанд, донистани обу ҳаво бошад — ба бехатар рафтор кардан. Ба корточкаҳо пахш кун.",
"Стоя, с уважением": "Ба по истода, бо эҳтиром",
