"Поворот на 180 градусов — это разворот": "Гардонидан ба 180 дараҷа — ин баргашт аст",
"Поворот на 90 градусов — четверть оборота, на 180 градусов — пол-оборота, рисунок окажется вверх ногами.": "Гардонидан ба 90 дараҷа — чоряки давр, ба 180 дараҷа — нимдавр, расм чаппа мешавад.",
"Поворот на 90 градусов — это четверть оборота": "Гардонидан ба 90 дараҷа — ин чоряки давр аст",
"Поворот на четверть оборота": "Гардонидан ба чоряки давр",
