"Позвать друга к экрану": "Дӯстро ба экран даъват кардан",
"Поздравляю! Ты узнал про правила безопасности, устройства ввода и вывода, файлы и папки, поиск в сети, клавиатуру, алгоритмы, Scratch, редактирование рисунка и звука и про роботов. Теперь закрепи знания в играх.": "Табрик мекунам! Ту дар бораи қоидаҳои бехатарӣ, дастгоҳҳои воридкунӣ ва баровардан, файлҳо ва папкаҳо, ҷустуҷӯ дар шабака, клавиатура, алгоритмҳо, Scratch, таҳрири расм ва садо ва дар бораи роботҳо фаҳмидӣ. Акнун донишҳоро дар бозиҳо мустаҳкам кун.",
