"Понимать алгоритм ветвления и записывать алгоритмы словами": "Алгоритми шохадорро фаҳмидан ва алгоритмҳоро бо калима сабт кардан",
"Поставить громче звук": "Садоро баландтар гузоштан",
"Поставить робота на бок": "Роботро ба паҳлӯ гузоштан",
