"Потрогать провода": "Ба симҳо даст задан",
"Похоже, что человек кричит": "Чунин менамояд, ки одам фарёд мезанад",
"Почему нельзя трогать провода и розетки?": "Чаро ба симҳо ва розеткаҳо даст задан мумкин нест?",
"Поёт": "Месарояд",
"Правила вежливого общения в сети": "Қоидаҳои муоширати хушмуомила дар шабака",
"Привет": "Салом",
"Привет! Это Барсик. Компьютер любит порядок. Давай узнаем, как работать за ним безопасно и как вежливо общаться в сети. Нажимай на карточки.": "Салом! Ман Барсик. Компютер тартибро дӯст медорад. Биё бифаҳмем, ки дар паси он чӣ тавр бехатар кор кардан лозим аст ва дар шабака чӣ тавр хушмуомила муошират кардан лозим аст. Ба корточкаҳо пахш кун.",
"Придумать идею проекта": "Ғояи лоиҳаро андеша кардан",
"Принтер печатает на бумаге": "Принтер бар рӯи коғаз чоп мекунад",
"Принтер печатает на бумаге, колонки и наушники воспроизводят звук. Все они — устройства вывода.": "Принтер бар рӯи коғаз чоп мекунад, баландгӯякҳо ва гӯшмонакҳо садоро мебароранд. Ҳамаи онҳо дастгоҳҳои баровардан мебошанд.",
"Принтер — устройство вывода": "Принтер — дастгоҳи баровардан аст",
"Пробел": "Фосила",
"Пробел делает промежуток между словами": "Фосила байни калимаҳо ҷой мегузорад",
"Пробел нужен, чтобы отделять слова друг от друга": "Фосила барои аз ҳамдигар ҷудо кардани калимаҳо лозим аст",
"Проверить его на другом надёжном источнике": "Онро дар манбаи дигари боэътимод санҷидан",
"Провода слишком красивые": "Симҳо хеле зебоянд",
"Программа героя": "Барномаи қаҳрамон",
"Программа для просмотра сайтов": "Барнома барои дидани сайтҳо",
"Программу загружают в робота и запускают": "Барномаро ба робот боргирӣ мекунанд ва оғоз мекунанд",
"Проект нужно показать классу и рассказать о нём": "Лоиҳаро бояд ба синф нишон дод ва дар бораи он нақл кард",
"Проект нужно сохранять": "Лоиҳаро бояд нигоҳ дошт",
