"Различать устройства ввода и вывода": "Дастгоҳҳои воридкунӣ ва бароварданро фарқ кардан",
"Размер можно увеличить": "Андозаро калон кардан мумкин аст",
"Размер можно уменьшить": "Андозаро хурд кардан мумкин аст",
"Размер рисунка можно увеличить или уменьшить.": "Андозаи расмро калон ё хурд кардан мумкин аст.",
