"Рисунок с подписью": "Расм бо зернавис",
"Робот выполняет программу, которую для него составили": "Робот барномаеро иҷро мекунад, ки барои он тартиб додаанд",
"Робот движется вперёд": "Робот ба пеш ҳаракат мекунад",
"Робот движется назад": "Робот ба қафо ҳаракат мекунад",
"Робот может ехать вперёд и назад с заданной скоростью. Расстояние можно задать числом оборотов колеса.": "Робот метавонад бо суръати додашуда ба пеш ва ба қафо равад. Масофаро бо шумораи гардишҳои чарх додан мумкин аст.",
"Робот поворачивает на заданный угол: 90 градусов — четверть оборота, 180 градусов — разворот.": "Робот ба кунҷи додашуда мегардад: 90 дараҷа — чоряки давр, 180 дараҷа — баргашт.",
"Робот сам решает, что делать, без программы": "Робот худаш қарор мекунад, ки чӣ кор кунад, бе барнома",
"Робот — устройство, которое выполняет программу, составленную человеком.": "Робот — дастгоҳест, ки барномаеро иҷро мекунад, ки одам тартиб додааст.",
"Роботы помогают людям. Давай узнаем, как устроен образовательный робот и как заставить его двигаться. Нажимай на карточки.": "Роботҳо ба одамон кумак мекунанд. Биё бифаҳмем, ки роботи таълимӣ чӣ тавр сохта шудааст ва чӣ тавр онро ба ҳаракат овардан лозим аст. Ба корточкаҳо пахш кун.",
"С вежливого приветствия": "Бо салом додани хушмуомила",
"С идеи начинается проект": "Лоиҳа аз ғоя оғоз мешавад",
"С крика": "Бо фарёд",
