"Блок двигает спрайт": "Блок спрайтро ҳаракат медиҳад",
"Блок запускает программу по нажатию клавиши": "Блок барномаро бо пахш кардани клавиша оғоз мекунад",
"Блок показывает слова персонажа": "Блок суханони персонажро нишон медиҳад",
"Бобры игры на скорость": "Қундузҳо: бозиҳо барои суръат",
"Бобры: где живут": "Қундузҳо: дар куҷо зиндагӣ мекунанд",
"Браузер": "Браузер",
"Браузер нужен, чтобы открывать сайты": "Браузер барои кушодани сайтҳо лозим аст",
"Браузер открывает сайты": "Браузер сайтҳоро мекушояд",
"Браузер — программа для просмотра сайтов. Адрес сайта вводят в адресную строку.": "Браузер — барномаи дидани сайтҳо аст. Суроғаи сайтро ба сатри суроға дохил мекунанд.",
"Буква А": "Ҳарфи А",
"Буквенные клавиши вводят буквы": "Клавишаҳои ҳарфӣ ҳарфҳоро дохил мекунанд",
"Буквы, цифры и пробел": "Ҳарфҳо, рақамҳо ва фосила",
"В адресной строке": "Дар сатри суроға",
"В адресную строку вводят адрес сайта": "Ба сатри суроға суроғаи сайтро дохил мекунанд",
"В алгоритме ветвления есть условие. Если оно верно, выполняется одно, иначе — другое.": "Дар алгоритми шохадор шарт ҳаст. Агар он дуруст бошад, яке иҷро мешавад, вагарна — дигаре.",
"В алгоритме ветвления путь не зависит ни от чего": "Дар алгоритми шохадор роҳ аз ҳеҷ чиз вобаста нест",
"В графическом редакторе": "Дар муҳаррири графикӣ",
"В игровой среде Scratch можно создать своих героев и заставить их двигаться и разговаривать. Нажимай на карточки.": "Дар муҳити бозии Scratch қаҳрамонони худро сохтан ва онҳоро ба ҳаракат овардан ва сӯҳбат кунондан мумкин аст. Ба корточкаҳо пахш кун.",
"В линейном алгоритме команды идут по порядку, и выбора нет.": "Дар алгоритми хаттӣ фармонҳо бо тартиб меоянд, ва интихоб нест.",
"В неё вводят запрос": "Ба он дархост дохил мекунанд",
"В папке": "Дар папка",
