"В сети можно писать обидные слова, ведь никто не видит": "Дар шабака сухани таҳқиромез навиштан мумкин аст, зеро касе намебинад",
"В сети общаются так же вежливо, как и в жизни": "Дар шабака ҳамон тавр хушмуомила муошират мекунанд, ки дар зиндагӣ",
"В строку поиска вводят запрос из нескольких ключевых слов. Например: бобры, где живут.": "Ба сатри ҷустуҷӯ дархостро аз якчанд калимаи калидӣ дохил мекунанд. Масалан: қундузҳо, дар куҷо зиндагӣ мекунанд.",
