"Вставка помещает текст в другую программу": "Гузоштан матнро ба барномаи дигар мегузорад",
"Всё, что написано в интернете, всегда правда": "Ҳар чизе, ки дар интернет навишта шудааст, ҳамеша ҳақиқат аст",
