"Выделение отмечает фрагмент": "Интихоб порчаро қайд мекунад",
"Выдели фрагмент, скопируй и вставь: получатся одинаковые детали, например несколько ёлочек.": "Порчаро интихоб кун, нусха бардор ва бигузор: тафсилоти якхела ҳосил мешавад, масалан, якчанд арчача.",
