"Выключить мотор": "Моторро хомӯш кардан",
"Героя можно нарисовать самому в графическом редакторе": "Қаҳрамонро худат дар муҳаррири графикӣ кашидан мумкин аст",
"Героя можно нарисовать самому во встроенном графическом редакторе: отразить, повернуть, изменить размер.": "Қаҳрамонро худат дар муҳаррири графикии дарунсохт кашидан мумкин аст: инъикос кардан, гардондан, андозаро тағйир додан.",
"Глазам нужен отдых от экрана": "Чашмон аз экран истироҳат лозим доранд",
