"Да, всё верно": "Бале, ҳама чиз дуруст аст",
"Датчик касания": "Сенсори ламс",
"Датчик касания реагирует на касание": "Сенсори ламс ба ламс вокуниш нишон медиҳад",
"Датчик касания сообщает роботу, что он коснулся предмета, например стены лабиринта.": "Сенсори ламс ба робот хабар медиҳад, ки вай ба ашё расид, масалан, ба девори лабиринт.",
