"Если лампа не горит — включить свет, иначе — читать": "Агар чароғ нагирад — чароғро даргирондан, вагарна — хондан",
"Если на улице дождь, взять зонт, иначе взять шапку": "Агар дар кӯча борон борад, чатр гирифтан, вагарна кулоҳ гирифтан",
"Если нужно узнать что-то новое, на помощь приходит интернет. Давай научимся искать в нём нужное. Нажимай на карточки.": "Агар чизи навро донистан лозим шавад, интернет ба кумак меояд. Биё ёд гирем, ки дар он чизи лозимиро ҷустуҷӯ кунем. Ба корточкаҳо пахш кун.",
"Если путь свободен — идти, иначе — обойти": "Агар роҳ озод бошад — рафтан, вагарна — гирд задан",
"Если светофор красный, стоять, иначе идти": "Агар светофор сурх бошад, истодан, вагарна рафтан",
