"Информация в компьютере хранится в файлах, а файлы лежат в папках. Давай научимся наводить порядок. Нажимай на карточки.": "Маълумот дар компютер дар файлҳо нигоҳ дошта мешавад, ва файлҳо дар папкаҳо мебошанд. Биё ёд гирем, ки тартиб оварем. Ба корточкаҳо пахш кун.",
"Информация: текст, рисунок или звук": "Маълумот: матн, расм ё садо",
"Искать информацию по теме и переносить данные между программами": "Дар мавзӯъ маълумот ҷустан ва додаҳоро байни барномаҳо интиқол додан",
"Исполнитель — тот, кто выполняет команды алгоритма: человек, робот или программа.": "Иҷрокунанда — онест, ки фармонҳои алгоритмро иҷро мекунад: одам, робот ё барнома.",
