"Использовать блок «Когда нажата клавиша»": "Блоки «Вақте ки клавиша пахш шуд»-ро истифода бурдан",
"Использовать блок «Сказать»": "Блоки «Гуфтан»-ро истифода бурдан",
"Источник найденных сведений можно не называть": "Манбаи маълумоти ёфташударо ном бурдан лозим нест",
"Исчезнет весь компьютер": "Тамоми компютер нопадид мешавад",
"Исчезнет только значок быстрого входа": "Танҳо нишончаи дастрасии зуд нопадид мешавад",
"Их нельзя пачкать": "Онҳоро ифлос кардан мумкин нест",
"Каждый по очереди говорит свою реплику": "Ҳар кас навбат гапи худро мегӯяд",
"Как задать расстояние, которое проедет робот?": "Масофаеро, ки робот мегузарад, чӣ тавр муайян кардан мумкин аст?",
"Как заставить робота повернуть на 90 градусов?": "Робот-ро чӣ тавр ба 90 дараҷа гардонидан мумкин аст?",
"Как защитить глаза при работе за экраном?": "Ҳангоми кор дар паси экран чашмонро чӣ тавр ҳифз кардан лозим аст?",
"Как лучше написать запрос для поиска?": "Дархостро барои ҷустуҷӯ чӣ тавр беҳтар навиштан лозим аст?",
"Как можно длиннее": "То ҳадди имкон дарозтар",
"Как называется то, что получается после записи?": "Он чи пас аз сабт ҳосил мешавад, чӣ ном дорад?",
"Как называют устройства, которые показывают информацию?": "Дастгоҳҳое, ки маълумотро нишон медиҳанд, чӣ ном доранд?",
"Как открыть контекстное меню?": "Менюи контекстиро чӣ тавр кушодан мумкин аст?",
"Как передать текст с сайта в документ?": "Матни сайтро чӣ тавр ба ҳуҷҷат интиқол додан мумкин аст?",
"Как получить второй такой же фрагмент рисунка?": "Порчаи дуюми ҳамонандро аз расм чӣ тавр гирифтан мумкин аст?",
"Как получить заглавную букву?": "Ҳарфи калонро чӣ тавр гирифтан мумкин аст?",
"Как сделать запись слышнее?": "Сабтро чӣ тавр шунавотар кардан мумкин аст?",
