"Как управлять героем с клавиатуры?": "Қаҳрамонро аз клавиатура чӣ тавр идора кардан мумкин аст?",
"Какая клавиша нужна?: Как вставить скопированный текст с клавиатуры?": "Кадом клавиша лозим аст?: Матни нусхабардоришударо аз клавиатура чӣ тавр гузоштан мумкин аст?",
"Какая клавиша нужна?: Как скопировать выделенный текст с клавиатуры?": "Кадом клавиша лозим аст?: Матни интихобшударо аз клавиатура чӣ тавр нусха бардоштан мумкин аст?",
"Какая клавиша нужна?: Какая клавиша находится длинной полосой внизу клавиатуры?": "Кадом клавиша лозим аст?: Кадом клавиша ҳамчун хати дароз дар поёни клавиатура ҷойгир аст?",
"Какая клавиша нужна?: Какую клавишу нажимают вместе с буквой, чтобы получить заглавную?": "Кадом клавиша лозим аст?: Кадом клавишаро якҷоя бо ҳарф пахш мекунанд, то ки ҳарфи калон гиранд?",
"Какая клавиша нужна?: Нужно напечатать слово с заглавной буквы. Что нажать вместе с буквой?": "Кадом клавиша лозим аст?: Бояд калимаро бо ҳарфи калон чоп кард. Якҷоя бо ҳарф чиро пахш кардан лозим аст?",
"Какая клавиша нужна?: Нужно передвинуть курсор вправо. Что нажать?": "Кадом клавиша лозим аст?: Бояд курсорро ба рост ҳаракат дод. Чиро пахш кардан лозим аст?",
"Какая клавиша нужна?: Нужно перейти на новую строку. Что нажать?": "Кадом клавиша лозим аст?: Бояд ба сатри нав гузашт. Чиро пахш кардан лозим аст?",
"Какая клавиша нужна?: Нужно сделать промежуток между словами. Что нажать?": "Кадом клавиша лозим аст?: Бояд байни калимаҳо фосила монд. Чиро пахш кардан лозим аст?",
"Какая клавиша нужна?: Нужно стереть букву слева от курсора. Что нажать?": "Кадом клавиша лозим аст?: Бояд ҳарфро аз чапи курсор тоза кард. Чиро пахш кардан лозим аст?",
"Какая клавиша нужна?: Нужно стереть букву справа от курсора. Что нажать?": "Кадом клавиша лозим аст?: Бояд ҳарфро аз рости курсор тоза кард. Чиро пахш кардан лозим аст?",
"Какое слово стоит в записи алгоритма ветвления?": "Кадом калима дар сабти алгоритми шохадор меистад?",
"Какое устройство входит в устройства ввода?": "Кадом дастгоҳ ба дастгоҳҳои воридкунӣ дохил мешавад?",
"Какое устройство нужно?: Какое устройство передаёт информацию в компьютер?": "Кадом дастгоҳ лозим аст?: Кадом дастгоҳ маълумотро ба компютер мерасонад?",
"Какое устройство нужно?: Какое устройство только показывает информацию?": "Кадом дастгоҳ лозим аст?: Кадом дастгоҳ маълумотро танҳо нишон медиҳад?",
"Какое устройство нужно?: Нужно выбрать картинку на экране. Что использовать?": "Кадом дастгоҳ лозим аст?: Бояд дар экран расмро интихоб кард. Чиро истифода бурдан лозим аст?",
"Какое устройство нужно?: Нужно записать свой голос. Что использовать?": "Кадом дастгоҳ лозим аст?: Бояд овози худро сабт кард. Чиро истифода бурдан лозим аст?",
"Какое устройство нужно?: Нужно напечатать слово. Что использовать?": "Кадом дастгоҳ лозим аст?: Бояд калимаро чоп кард. Чиро истифода бурдан лозим аст?",
"Какое устройство нужно?: Нужно получить рисунок на бумаге. Что использовать?": "Кадом дастгоҳ лозим аст?: Бояд расмро бар рӯи коғаз гирифт. Чиро истифода бурдан лозим аст?",
"Какое устройство нужно?: Нужно послушать музыку всем классом. Что использовать?": "Кадом дастгоҳ лозим аст?: Бояд мусиқиро бо тамоми синф гӯш кард. Чиро истифода бурдан лозим аст?",
"Какое устройство нужно?: Нужно послушать музыку, чтобы никому не мешать. Что использовать?": "Кадом дастгоҳ лозим аст?: Бояд мусиқиро гӯш кард, ки ба касе халал нарасонад. Чиро истифода бурдан лозим аст?",
"Какое устройство нужно?: Нужно посмотреть рисунок. Что использовать?": "Кадом дастгоҳ лозим аст?: Бояд расмро дид. Чиро истифода бурдан лозим аст?",
