"Какой алгоритм верный?: Исполнитель Робот должен дойти до двери. Какой алгоритм линейный?": "Кадом алгоритм дуруст аст?: Иҷрокунандаи Робот бояд ба дар расад. Кадом алгоритм хаттӣ аст?",
