"Какой инструмент нужен?: Нужно получить ещё одну такую же ёлочку. Что сделать?": "Кадом асбоб лозим аст?: Бояд боз як арчачаи ҳамонандро гирифт. Чӣ кор кардан лозим аст?",
"Какой инструмент нужен?: Нужно сделать рисунок зеркально. Что сделать?": "Кадом асбоб лозим аст?: Бояд расмро оинавӣ сохт. Чӣ кор кардан лозим аст?",
