"Рядом с нами всегда люди: в семье, в школе, в транспорте. Вместе они — общество. Давай узнаем, как жить в нём дружно. Нажимай на карточки.": "Дар паҳлӯи мо ҳамеша одамон ҳастанд: дар оила, дар мактаб, дар нақлиёт. Онҳо якҷоя — ҷамъият аст. Биё бифаҳмем, ки дар он чӣ тавр дӯстона зиндагӣ кардан лозим аст. Ба корточкаҳо пахш кун.",
